VALUES ('test_resource_tool_id', 'test_resource_project_id', 'mage_translate_1', 'mage_translate_1', '文本翻译工具，主要将输入中文转成英文', '', NULL, 'project', '{"basic_info":{"host":"127.0.0.1:4878","path":"","protocol":"http"},"tool_info":[{"tool_id":"0","tool_display_name":"mage_translate_1","tool_chinese_name":"mage_translate_1","tool_desc":"文本翻译工具，主要将输入中文转成英文","url":"http://127.0.0.1:4878/translate","method":"POST","headers":{"Content-Type":"application/json"},"path":"/translate"}]}', '{}', '[{"tool_id":"0","input_schema":"{\"type\":\"object\",\"properties\":{\"text\":{\"location\":\"Body\",\"validate_rule\":\"\",\"validate_type\":\"CHAR\",\"validated\":false,\"name_cn\":\"待翻译的文本\",\"type\":\"string\",\"description\":\"待翻译的文本，标点符号都是中文标点符号\"}},\"required\":[\"text\"]}"}]', '[{"tool_id":"0","output_schema":"{\"type\":\"object\",\"properties\":{\"response_data\":{\"type\":\"string\",\"description\":\"返回数据\"}},\"required\":[\"response_data\"]}"}]', '[{"tool_id":"0","intf_type":"blocking"}]', 'custom', NULL, '官方预置', '6f80301edacc43728bf47b6a6484d512', '2025-09-09 20:58:20', '2025-11-15 14:17:41', '[{"tool_id":"0","test_resource_status":2}]', '1762262594882', NULL, '[{"tool_id":"0","is_input_list":false}]', '[{"tool_id":"0","is_output_list":false}]', 0, 'default', NULL, 1, 'api', 0, NULL);

