VALUES ('test_resource_mcp_id', '空白模板233', 'Empty Template', '基于空白模板快速构建自己的业务逻辑233',
        'Base on empty template to create mcp service', '', null, 'success', null, null, null, 0, 'system', 'system',
        '2025-08-07 21:08:00', 'system', '2025-08-07 21:11:57', '2', null, '{
  "mcpServers" : {
    "example-sse" : {
      "url" : "http://xxxx:8080/sse"
    }
  }
}', '[{"name":"createCalendar","description":"日历，日程，提醒等类似于备忘录类事件新增","inputSchema":{"type":"object","properties":{"content":{"type":"string","description":"内容"},"summary":{"type":"string","description":"综述 没有特别注释时和内容字段一样"},"receiverUserList":{"type":"array","items":{"type":"string"},"description":"接受者ID集合，最大容量500"},"reminder":{"type":"object","properties":{"minutes":{"type":"number","description":"距开始时多久进行提醒(单位:分钟)"}},"required":["minutes"],"additionalProperties":false},"startTime":{"type":"string","description":"日历开始时间，GMT+0800（时区）时间字符串，格式为: YYYY-MM-DD HH:MM 如果没有指定开始时间或填空串，则表示日历5分钟后开始"},"endTime":{"type":"string","description":"日历结束时间，GMT+0800（时区）时间字符串，格式为: YYYY-MM-DD HH:MM 如果没有指定开始时间或填空串，则表示开始时间往后30分钟"},"location":{"type":"string","description":"地址"},"recurrence":{"type":"object","properties":{"frequency":{"type":"string","description":"重复基准， ''DAILY'', ''WEEKLY'', ''MONTHLY'', ''YEARLY'' "},"count":{"type":"number","description":"重复次数"},"until":{"type":"string","description":"设置截止日期，不可与count同时出现, 格式为：YYYY-MM-DD HH:MM"},"days":{"type":"array","items":{"type":"string"},"description":"当frequency为MONTHLY or YEARLY时，表示周中的哪些天。例如   [{''ordwk'':3, ''weekday'': ''SU''}] 表示第三个周日"},"interval":{"type":"number","description":"依赖freq，重复周期。如：frequency=DAILY;interval=8. 每隔8天重复一次"},"monthdays":{"type":"array","items":{"type":"number"},"description":"单月内，哪些天"},"months":{"type":"array","items":{"type":"number"},"description":"一年内，哪些月份"}},"required":["frequency","count","until","days","interval","monthdays","months"],"additionalProperties":false,"description":"日历重复规则，示例："recurrence": {     "frequency": "DAILY",     "interval":2,     "count":10 } 表示：每隔一天，共发生10次。  改字段在创建普通日程，或者没有明确表示需要重复的日程时不填"}},"required":["content","summary","receiverUserList","startTime","endTime"],"additionalProperties":false}},{"name":"queryCalendar","description":"查询用户指定时间段的日程，日历","inputSchema":{"type":"object","properties":{"userId":{"type":"string","description":"当前用户的userid"},"startTime":{"type":"string","description":"用户查询日历的开始时间，GMT+0800（时区）时间字符串，格式为: YYYY-MM-DD HH:MM 如果没有指定开始时间或填空串, 则取当前时间"},"endTime":{"type":"string","description":"用户查询日历的结束时间，GMT+0800（时区）时间字符串，格式为: YYYY-MM-DD HH:MM 如果没有指定开始时间或填空串, 则取当前时间的后一天"}},"required":["userId","startTime","endTime"],"additionalProperties":false}},{"name":"updateCalendar","description":"调整和修改指定日历，通过时间或者名称匹配日历的calUid和上下文中查询出来的结果作为基础进行更新","inputSchema":{"type":"object","properties":{"calUid":{"type":"string","description":"待更新日历的日历id"},"content":{"type":"string","description":"内容"},"summary":{"type":"string","description":"综述，非必填"},"receiverUserList":{"type":"array","items":{"type":"string"},"description":"接受者ID集合，最大容量500, 如果接收人为空 则从上下文中找到查询用户的userId"},"reminder":{"type":"object","properties":{"minutes":{"type":"number","description":"距开始时多久进行提醒(单位:分钟)"}},"required":["minutes"],"additionalProperties":false},"startTime":{"type":"string","description":"日历开始时间，GMT+0800（时区）时间字符串，格式为: YYYY-MM-DD HH:MM 如果没有指定开始时间或填空串，则表示日历5分钟后开始"},"endTime":{"type":"string","description":"日历结束时间，GMT+0800（时区）时间字符串，格式为: YYYY-MM-DD HH:MM 如果没有指定开始时间或填空串，则表示开始时间往后30分钟"},"location":{"type":"string","description":"地址"},"recurrence":{"type":"object","properties":{"frequency":{"type":"string","description":"重复基准， ''DAILY'', ''WEEKLY'', ''MONTHLY'', ''YEARLY'' "},"count":{"type":"number","description":"重复次数"},"until":{"type":"string","description":"设置截止日期，不可与count同时出现, 格式为：YYYY-MM-DD HH:MM"},"days":{"type":"array","items":{"type":"string"},"description":"当frequency为MONTHLY or YEARLY时，表示周中的哪些天。例如   [{''ordwk'':3, ''weekday'': ''SU''}] 表示第三个周日"},"interval":{"type":"number","description":"依赖freq，重复周期。如：frequency=DAILY;interval=8. 每隔8天重复一次"},"monthdays":{"type":"array","items":{"type":"number"},"description":"单月内，哪些天"},"months":{"type":"array","items":{"type":"number"},"description":"一年内，哪些月份"}},"required":["frequency","count","until","days","interval","monthdays","months"],"additionalProperties":false,"description":"日历重复规则，示例："recurrence": {     "frequency": "DAILY",     "interval":2,     "count":10 } 表示：每隔一天，共发生10次。  改字段在创建普通日程，或者没有明确表示需要重复的日程时不填"}},"required":["calUid","content","summary","receiverUserList","reminder","startTime","endTime","location"],"additionalProperties":false}},{"name":"deleteCalendar","description":"删除日历服务","inputSchema":{"type":"object","properties":{"calUid":{"type":"string","description":"待更新日历的日历id"},"receiverUserList":{"type":"array","items":{"type":"string"},"description":"接受者ID集合，最大容量500, 需要删除的人员列表"}},"required":["calUid","receiverUserList"],"additionalProperties":false}},{"name":"queryFreebusy","description":"查询用户闲忙和日程安排服务，用于查询用户在指定时间内是否有会议和日程的冲突","inputSchema":{"type":"object","properties":{"users":{"type":"array","items":{"type":"string"},"description":"需要查询人员列表，最大100"},"startTime":{"type":"string","description":"日历查询开始时间，GMT+0800（时区）时间字符串，格式为: YYYY-MM-DD HH:MM 如果没有指定开始时间或填空串，则表示当天开始查询"},"endTime":{"type":"string","description":"日历查询结束时间，GMT+0800（时区）时间字符串，格式为: YYYY-MM-DD HH:MM 如果没有指定开始时间或填空串，则表示开始时间往后1天"},"calUid":{"type":"string","description":"日历id,用于根据uid排除查询某日程"}},"required":["users","startTime","endTime"],"additionalProperties":false}}]', 'sse', 'SSE', null, '1', null, '空白模板233-g6dypa9D-AIAE', null, '533c8eef0d55426d9f58ed4298f3a88c', 'test_resource_project_id', 'default', 'IAM-TOKEN');


